  "description": "OpenCode and magpie provider plugin for OpenCSG AI Gateway with API key and OAuth login",
  "type": "module",
  "main": "./magpie.mjs",
  "exports": {
    ".": "./index.mjs",
    "./magpie": "./magpie.mjs"
  },
  "files": [
    "index.mjs",
    "magpie.mjs",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "magpie",
    "magpie-plugin",
    "opencsg",
    "csghub",
    "aigateway",
    "provider"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/CheinTian/magpie-opencsg-auth.git"
  },
  "scripts": {
    "test": "bun test",
    "check": "bun scripts/check.mjs"
  },
  "magpie": {
    "icon": "https://opencsg.com/images/favicon.ico",
    "maxConcurrency": 8
  },
  "engines": {
    "bun": ">=1.0.0"
  }
